static void
poly_cbd_eta2(poly *r, const unsigned char buf[128])
{
    unsigned int i, j;
    uint32_t     t, d;
    int16_t      a, b;

    for (i = 0; i < MLKEM768_N / 8; i++) {
        t = (uint32_t) buf[4 * i] | ((uint32_t) buf[4 * i + 1] << 8) |
            ((uint32_t) buf[4 * i + 2] << 16) | ((uint32_t) buf[4 * i + 3] << 24);

        d = t & 0x55555555;
        d += (t >> 1) & 0x55555555;

        for (j = 0; j < 8; j++) {
            a                    = (d >> (4 * j)) & 0x3;
            b                    = (d >> (4 * j + 2)) & 0x3;
            r->coeffs[8 * i + j] = a - b;
        }
    }
